begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to cuevo_api,cuevo_worker;
set local search_path=extensions,pg_catalog;
select no_plan();
-- Isolate the synthetic learner projection inside this rollback fixture, even after repeated demos.
delete from app.learner_state_snapshots;delete from internal.processed_events;
delete from app.current_results;delete from app.current_rubric_results;

create temporary table support_ids(baseline uuid,recommendation uuid,intervention uuid,followup uuid,outcome uuid,event_id uuid,lease uuid);
grant select,insert,update on support_ids to cuevo_api,cuevo_worker;
insert into app.courses(school_id,id,class_id,subject_id,created_by,title,description,status)values('10000000-0000-4000-8000-000000000001','89000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','43000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Support source golden','Synthetic','PUBLISHED');
insert into app.assessments(school_id,id,course_id,created_by,title,instructions,max_score,academic_reference_id,policy_version)values
('10000000-0000-4000-8000-000000000001','89000000-0000-4000-8000-000000000002','89000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Baseline','Synthetic',10,'61000000-0000-4000-8000-000000000001',2),
('10000000-0000-4000-8000-000000000001','89000000-0000-4000-8000-000000000003','89000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000004','Follow-up','Synthetic',10,'61000000-0000-4000-8000-000000000001',2);
insert into app.submissions(school_id,id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001','89000000-0000-4000-8000-000000000004','89000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000012','Synthetic baseline source');
set local role cuevo_api;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);
insert into support_ids(baseline)select internal.release_marking(internal.mark_submission('89000000-0000-4000-8000-000000000004',0,'Reviewed baseline',2,0,true),1,false);
update support_ids set recommendation=internal.create_recommendation(baseline,'{"observation":"Recorded zero","interpretation":"One source","recommendation":"Try practice","rationale":"Review example","uncertainty":"Not causal evidence","activityTitle":"Approved practice","instructions":"Review the example"}');
select internal.decide_recommendation((select recommendation from support_ids),'APPROVE','Teacher approved',null,null);
update support_ids set intervention=(select i.id from app.interventions i where i.recommendation_id=support_ids.recommendation);
update support_ids set event_id=internal.enqueue_event('recommendation.approved','intervention',recommendation,1,'{"learnerId":"forged"}','support-approval-golden');
reset role;
update support_ids set lease='89000000-0000-4000-8000-000000000005';
update internal.outbox_events set state='PROCESSING',lease_token=(select lease from support_ids),lease_until=clock_timestamp()+interval'60 seconds'where id=(select event_id from support_ids);
set local role cuevo_worker;
select lives_ok($$select internal.process_learner_event((select event_id from support_ids),(select lease from support_ids))$$,'approval source refreshes assigned support');
select throws_ok('select internal.refresh_support_impact(null,null)','42501',null,'worker cannot invoke unrestricted projection helper');
reset role;
select is((select support->'items'->0->>'id'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),(select intervention::text from support_ids),'support derived from persisted intervention not metadata');
select is((select impact->>'status'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'unmeasured','approval is not measured outcome');
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select internal.complete_intervention((select intervention from support_ids),'Synthetic reflection');
update support_ids set event_id=internal.enqueue_event('intervention.completed','intervention',intervention,1,'{}','support-completion-golden');
reset role;
update internal.outbox_events set state='PROCESSING',lease_token=(select lease from support_ids),lease_until=clock_timestamp()+interval'60 seconds'where id=(select event_id from support_ids);
set local role cuevo_worker;select lives_ok($$select internal.process_learner_event((select event_id from support_ids),(select lease from support_ids))$$,'immutable completion refreshes support');reset role;
select is((select support->'items'->0->>'status'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'COMPLETED','completed support remains awaiting measurement');
insert into app.submissions(school_id,id,assessment_id,learner_id,content)values('10000000-0000-4000-8000-000000000001','89000000-0000-4000-8000-000000000006','89000000-0000-4000-8000-000000000003','20000000-0000-4000-8000-000000000012','Synthetic post-intervention evidence');
set local role cuevo_api;select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.link_reassessment((select intervention from support_ids),'89000000-0000-4000-8000-000000000003');
select internal.append_audit('reassessment.linked','intervention',(select intervention from support_ids),'support-link-golden','succeeded','{}');
update support_ids set event_id=internal.enqueue_event('reassessment.linked','intervention',intervention,1,'{}','support-link-golden');
update support_ids set followup=internal.release_marking(internal.mark_submission('89000000-0000-4000-8000-000000000006',4,'Reviewed follow-up',2,0,true),1,false);
reset role;update internal.outbox_events set state='PROCESSING',lease_token=(select lease from support_ids),lease_until=clock_timestamp()+interval'60 seconds'where id=(select event_id from support_ids);
set local role cuevo_worker;select lives_ok($$select internal.process_learner_event((select event_id from support_ids),(select lease from support_ids))$$,'linked source follow-up refreshes support');reset role;
set local role cuevo_api;update support_ids set outcome=internal.measure_intervention(intervention,followup,2);
select internal.append_audit('outcome.measured','outcome',(select outcome from support_ids),'support-measured-golden','succeeded','{}');
update support_ids set event_id=internal.enqueue_event('outcome.measured','outcome',outcome,1,'{}','support-measured-golden');
reset role;update internal.outbox_events set state='PROCESSING',lease_token=(select lease from support_ids),lease_until=clock_timestamp()+interval'60 seconds'where id=(select event_id from support_ids);
-- Delayed completion delivery must not produce a MEASURED item with a missing completion source.
delete from internal.processed_events where school_id='10000000-0000-4000-8000-000000000001'and source_type='INTERVENTION_COMPLETION'and source_id in(select id from app.intervention_completions where intervention_id=(select intervention from support_ids));
set local role cuevo_worker;select lives_ok($$select internal.process_learner_event((select event_id from support_ids),(select lease from support_ids))$$,'out-of-order measured event retains valid awaiting-source state');reset role;
select is((select impact->>'status'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'unmeasured','outcome waits for processed completion source');
select isnt((select support->'items'->0->>'status'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'MEASURED','missing completion event cannot create invalid measured support');
select is((select support->'items'->0->'followUpAssessmentId'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'null'::jsonb,'processed link cannot appear on support whose completion is unprocessed');
delete from internal.processed_events where school_id='10000000-0000-4000-8000-000000000001'and source_type='REASSESSMENT'and source_id=(select intervention from support_ids);
update support_ids set event_id=gen_random_uuid();
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key,state,lease_token,lease_until)values('10000000-0000-4000-8000-000000000001',(select event_id from support_ids),'20000000-0000-4000-8000-000000000012','intervention.completed','intervention',(select intervention from support_ids),1,'{}','delayed-completion-golden','PROCESSING',(select lease from support_ids),clock_timestamp()+interval'60 seconds');
set local role cuevo_worker;select lives_ok($$select internal.process_learner_event((select event_id from support_ids),(select lease from support_ids))$$,'late completion source reconciles awaiting-link state');reset role;
select is((select impact->>'status'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'unmeasured','measurement also waits for processed linked assessment');
update support_ids set event_id=gen_random_uuid();
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key,state,lease_token,lease_until)values('10000000-0000-4000-8000-000000000001',(select event_id from support_ids),'20000000-0000-4000-8000-000000000004','reassessment.linked','intervention',(select intervention from support_ids),1,'{}','delayed-link-golden','PROCESSING',(select lease from support_ids),clock_timestamp()+interval'60 seconds');
set local role cuevo_worker;select lives_ok($$select internal.process_learner_event((select event_id from support_ids),(select lease from support_ids))$$,'late linked assessment reconciles measured impact');reset role;
select is((select impact->>'status'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'measured','impact is measured only from immutable outcome');
select is((select impact->'outcomes'->0->'baseline'->>'score'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'0','explicit zero baseline remains source-backed zero');
select is((select impact->'outcomes'->0->>'difference'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'4','native difference preserved');
select is((select impact->'outcomes'->0->>'limitation'from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),'OBSERVED_CHANGE_NOT_CAUSAL_PROOF','no causal certainty inferred');
select is((select jsonb_array_length(support->'activeInterventionIds')from app.learner_state_snapshots where school_id='10000000-0000-4000-8000-000000000001'and learner_id='20000000-0000-4000-8000-000000000012'),0,'measured support leaves active queue');
insert into internal.outbox_events(school_id,id,actor_id,type,entity_type,entity_id,version,metadata,deduplication_key,state,lease_token,lease_until)values('10000000-0000-4000-8000-000000000002','89000000-0000-4000-8000-000000000099','20000000-0000-4000-8000-000000000133','outcome.measured','outcome',(select outcome from support_ids),1,'{}','foreign-outcome-golden','PROCESSING','89000000-0000-4000-8000-000000000005',clock_timestamp()+interval'60 seconds');
set local role cuevo_worker;select throws_ok($$select internal.process_learner_event('89000000-0000-4000-8000-000000000099','89000000-0000-4000-8000-000000000005')$$,'22023',null,'foreign school cannot project another learner outcome');reset role;
select is((select count(*)from internal.processed_events where event_id='89000000-0000-4000-8000-000000000099'),0::bigint,'invalid outcome leaves no processed marker');
select *from finish();
rollback;
